import fs from 'fs';import path from 'path';const root='sep18-full-current-audit-combined';const files=[];function walk(d){for(const e of fs.readdirSync(d,{withFileTypes:true})){const p=path.join(d,e.name);if(e.isDirectory())walk(p);else if(e.name==='results.json')files.push(p)}}walk(root);const rows=[];for(const f of files){try{const j=JSON.parse(fs.readFileSync(f,'utf8'));if(Array.isArray(j.rows))rows.push(...j.rows)}catch{}}const ok=rows.filter(r=>r.httpStatus===200&&r.previewOk&&!r.error),bad=rows.filter(r=>!(r.httpStatus===200&&r.previewOk&&!r.error));const avg=(g,k)=>{const a=ok.filter(x=>x.group===g);return a.length?Math.round(a.reduce((s,x)=>s+(x[k]||0),0)/a.length):0};const ranked=[...ok].sort((a,b)=>(b.loadMs||0)-(a.loadMs||0));const summary={generatedAt:new Date().toISOString(),total:rows.length,valid:ok.length,invalid:bad.length,counts:{homepage:rows.filter(x=>x.group==='homepage').length,stateGuardRoot:rows.filter(x=>x.group==='state-guard-root').length},averages:{homepage:{loadMs:avg('homepage','loadMs'),fcpMs:avg('homepage','fcpMs'),lcpMs:avg('homepage','lcpMs')},stateGuardRoot:{loadMs:avg('state-guard-root','loadMs'),fcpMs:avg('state-guard-root','fcpMs'),lcpMs:avg('state-guard-root','lcpMs')}},slowest:ranked.slice(0,20),invalidRows:bad,rows};fs.mkdirSync('sep18-full-current-audit-final',{recursive:true});fs.writeFileSync('sep18-full-current-audit-final/summary.json',JSON.stringify(summary,null,2));const md=['# Sep18 Full Current Draft Load Audit','',`Total: ${summary.total} | Valid: ${summary.valid} | Invalid: ${summary.invalid}`,`Homepage: ${summary.counts.homepage} | State Guard root: ${summary.counts.stateGuardRoot}`,'',`Homepage average load: ${summary.averages.homepage.loadMs} ms`,`State Guard average load: ${summary.averages.stateGuardRoot.loadMs} ms`,'','## Slowest valid destinations',...summary.slowest.map((r,i)=>`${i+1}. ${r.group} — ${r.label} — load ${r.loadMs} ms; FCP ${r.fcpMs} ms; LCP ${r.lcpMs} ms; ${Math.round((r.transferBytes||0)/1024)} KB; ${r.resources} resources; ${r.domNodes} DOM nodes`),'','## Invalid',...bad.map(r=>`- ${r.group} — ${r.label} — HTTP ${r.httpStatus} previewOk=${r.previewOk} error=${r.error||''}`)];fs.writeFileSync('sep18-full-current-audit-final/AUDIT.md',md.join('\n'));console.log('FULLSUMMARY',JSON.stringify({total:summary.total,valid:summary.valid,invalid:summary.invalid,counts:summary.counts,averages:summary.averages,slowest:summary.slowest.slice(0,12).map(r=>({group:r.group,label:r.label,route:r.route,loadMs:r.loadMs,fcpMs:r.fcpMs,lcpMs:r.lcpMs,kb:Math.round((r.transferBytes||0)/1024),resources:r.resources,dom:r.domNodes,cards:r.productCards})),invalidRows:bad.map(r=>({group:r.group,label:r.label,route:r.route,http:r.httpStatus,previewOk:r.previewOk,error:r.error}))}));if(bad.length)process.exitCode=2;